import React, { useState } from 'react';
import Navbar from './components/Navbar';
import RoleSelection from './components/RoleSelection';
import Login from './components/Login';
import UniversityUpload from './components/UniversityUpload';
import UniversityReview from './components/UniversityReview';
import UniversitySuccess from './components/UniversitySuccess';
import VerifierUpload from './components/VerifierUpload';
import VerificationResult from './components/VerificationResult';

function App() {
    const [currentRole, setCurrentRole] = useState(null);
    const [isLoggedIn, setIsLoggedIn] = useState(false);
    const [userData, setUserData] = useState(null);
    const [universityStep, setUniversityStep] = useState('upload');
    const [extractedData, setExtractedData] = useState(null);
    const [confirmationData, setConfirmationData] = useState(null);
    const [verifierStep, setVerifierStep] = useState('upload');
    const [verificationData, setVerificationData] = useState(null);

    const handleRoleSelection = (role) => setCurrentRole(role);
    const handleLoginSuccess = (data) => { setUserData(data); setIsLoggedIn(true); };
    const handleLogout = () => {
        setCurrentRole(null); setIsLoggedIn(false); setUserData(null);
        setUniversityStep('upload'); setExtractedData(null); setConfirmationData(null);
        setVerifierStep('upload'); setVerificationData(null);
    };
    const handleBackToRoleSelection = () => setCurrentRole(null);
    const handleUploadSuccess = (data) => { setExtractedData(data); setUniversityStep('review'); };
    const handleConfirmSuccess = (data) => { setConfirmationData(data); setUniversityStep('success'); };
    const handleNewCertificate = () => { setUniversityStep('upload'); setExtractedData(null); setConfirmationData(null); };
    const handleBackToUpload = () => { setUniversityStep('upload'); setExtractedData(null); };
    const handleVerificationSuccess = (data) => { setVerificationData(data); setVerifierStep('result'); };
    const handleNewVerification = () => { setVerifierStep('upload'); setVerificationData(null); };

    const renderContent = () => {
        if (!currentRole) return <RoleSelection onSelectRole={handleRoleSelection} />;
        if (!isLoggedIn) return <Login role={currentRole} onLoginSuccess={handleLoginSuccess} onBack={handleBackToRoleSelection} />;
        if (currentRole === 'university') {
            if (universityStep === 'upload') return <UniversityUpload onUploadSuccess={handleUploadSuccess} />;
            if (universityStep === 'review') return <UniversityReview extractedData={extractedData} onConfirmSuccess={handleConfirmSuccess} onBack={handleBackToUpload} />;
            if (universityStep === 'success') return <UniversitySuccess confirmationData={confirmationData} onNewCertificate={handleNewCertificate} />;
        }
        if (currentRole === 'verifier') {
            if (verifierStep === 'upload') return <VerifierUpload onVerificationSuccess={handleVerificationSuccess} />;
            if (verifierStep === 'result') return <VerificationResult verificationData={verificationData} onNewVerification={handleNewVerification} />;
        }
        return <RoleSelection onSelectRole={handleRoleSelection} />;
    };

    return (
        <div className="App">
            <Navbar role={currentRole} onLogout={isLoggedIn ? handleLogout : null} />
            <main className="main-content">{renderContent()}</main>
            <footer className="footer"><p>© 2026 Certificate Verification System | Powered by AI & Blockchain</p></footer>
        </div>
    );
}

export default App;
